import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Spherical component
        sphere = np.sum(x**2)
        # Sinusoidal modulation (wavelength scales with dimension)
        wavelength = 2 * np.pi / (self.dim + 1)
        sin_mod = np.sum(np.sin(x * wavelength))
        # Combined with a scaling factor to balance the components
        return sphere + 0.1 * sin_mod * np.sqrt(sphere + 1e-10)

