import numpy as np

class SmoothWavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Gaussian weight to smooth the sinusoidal modulation
        gaussian_weight = np.exp(-0.5 * (x / 3)**2)
        return np.sum(x**2 + 0.05 * gaussian_weight * np.sin(3 * np.pi * x))

